/* ══════════════════════════════════════════════════════════════════════
   PAGE NAV (S-004, R-013)

   SELECTION LIVES HERE, not in the DOM. The old implementation kept the
   current page in a set of hidden radio inputs and read it back with
   document.querySelector('input[name="tab"]:checked'), which meant the
   selection was a property of markup that renderTabs threw away and rebuilt.
   It is now a module variable, and selectTab-through-click plus
   selectSearchTab() are its only writers. The external callers that used to
   poke the radios call selectSearchTab().

   The panel is built ONCE and mutated, not rebuilt per render, because the
   scroll affordance attaches observers to the well; rebuilding the tree
   around it would strand them.
   ══════════════════════════════════════════════════════════════════════ */

import './tabs.css';
import { DEFAULT_TABS } from '../../constants/defaults.js';
import { ContextMenu } from '../contextMenu/contextMenu.js';
import { openTabDialog } from '../bookmarks/bookmarkDialog.js';
import { BookmarkDB } from '../../services/bookmarksDB.js';
import { attachScrollAffordance } from '../shared/scrollAffordance.js';
import {
  activeTabs, setActiveTabs, currentBookmarkPage
} from '../../pages/newtab/newtabState.js';

let _onTabClick = null;
let _onNavigateToSearch = null;

/* The filter field is what separates this from a plain menu, and it should not
   appear in order to search two rows. Above this many pages it earns its place.
   Was 6, which meant the field was invisible on a profile with a handful of
   pages, i.e. the feature was hidden from exactly the person who chose it
   (R-014). Three keeps a near-empty profile from being shown a search box while
   making the field appear as soon as the list is worth searching. */
const FILTER_THRESHOLD = 3;

let selectedTabId = 'search';
let els = null;        // built once by buildShell()
let affordance = null; // { refresh, host } from the shared control
let filterQuery = '';

export function setTabNavigationCallbacks({ onTabClick, onNavigateToSearch }) {
  _onTabClick = onTabClick;
  _onNavigateToSearch = onNavigateToSearch;
}

export async function initializeTabs() {
  return new Promise((resolve) => {
    window.chrome.storage.sync.get(["activeTabs"], (result) => {
      if (result.activeTabs && Array.isArray(result.activeTabs)) { setActiveTabs(result.activeTabs) }
      else { setActiveTabs([...DEFAULT_TABS]); saveTabs() }
      renderTabs(); resolve()
    })
  })
}

export function saveTabs() { window.chrome.storage.sync.set({ activeTabs: activeTabs }) }

/** Select the Home/search page. The callers that used to set .checked on a
 *  hidden radio (newtab.js on pageshow, and the delete paths below) call this,
 *  so there is one definition of "we are on Home" rather than two. */
export function selectSearchTab() {
  const home = activeTabs.find(t => t.type === 'search') || activeTabs[0];
  if (home) { selectedTabId = home.id; syncSelection(); }
}

/* ── Shell ─────────────────────────────────────────────────────────────── */

function el(tag, className, text) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

function buildShell(container) {
  container.className = 'page-nav';
  container.innerHTML = '';

  const trigger = el('button', 'page-nav-trigger');
  trigger.type = 'button';
  trigger.setAttribute('aria-haspopup', 'true');
  trigger.setAttribute('aria-expanded', 'false');
  const current = el('span', 'page-nav-current');
  const count = el('span', 'page-nav-count');
  trigger.append(current, count, el('span', 'page-nav-chevron'));

  const panel = el('div', 'page-nav-panel');
  panel.hidden = true;

  const filter = el('input', 'page-nav-filter');
  filter.type = 'text';
  filter.placeholder = 'Find a page';
  filter.setAttribute('aria-label', 'Find a page');
  filter.autocomplete = 'off';

  const well = el('div', 'page-nav-well');
  const empty = el('div', 'page-nav-empty', 'No page by that name');
  empty.hidden = true;

  /* R-014: the scrim recedes the page behind the panel, which used to float
     over live content and collide with the bookmark columns. It is a sibling
     of the panel, not a wrapper, so the panel and trigger paint above it. */
  const scrim = el('div', 'page-nav-scrim');
  scrim.hidden = true;

  panel.append(filter, well, empty);
  container.append(trigger, scrim, panel);

  /* The shared control (R-010), not a private fade: the well scrolls past four
     pages and base.css hides scrollbars everywhere, so it needs the same
     two-way fade and count the bookmark wells and the settings list use. It
     wraps the well in its own positioned host, which is why the shell is built
     once: re-rendering the tree would leave that wrapper observing dead nodes. */
  /* No `noun`: every other adopter leaves it empty and reads "5 below", and a
     noun here also went ungrammatical at one ("1 pages below"). R-014. */
  affordance = attachScrollAffordance(well, { items: ':scope > .page-nav-row' });

  els = { container, trigger, current, count, panel, scrim, filter, well, empty };

  trigger.addEventListener('click', (e) => { e.stopPropagation(); setOpen(els.panel.hidden); });

  filter.addEventListener('input', () => { filterQuery = filter.value.trim(); applyFilter(); });
  filter.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      const first = visibleRows()[0];
      if (first) { e.preventDefault(); first.click(); }
    } else if (e.key === 'ArrowDown') {
      const first = visibleRows()[0];
      if (first) { e.preventDefault(); first.focus(); }
    }
  });

  /* Arrow keys walk the rows, so the panel is usable without a pointer. The
     old menu could not be reached by keyboard at all: its reveal depended on
     :focus-within over inputs that were display:none and so unfocusable. */
  well.addEventListener('keydown', (e) => {
    if (e.key !== 'ArrowDown' && e.key !== 'ArrowUp') return;
    const rows = visibleRows();
    const i = rows.indexOf(document.activeElement);
    if (i === -1) return;
    e.preventDefault();
    const next = rows[e.key === 'ArrowDown' ? i + 1 : i - 1];
    if (next) next.focus();
    else if (e.key === 'ArrowUp' && !filter.hidden) filter.focus();
  });

  /* The scrim is INSIDE the container, so a container.contains() test alone
     would treat a backdrop click as a click on the nav and keep the panel open.
     It is named explicitly as a dismissal surface, which is also what the rest
     of the extension does with a backdrop. */
  document.addEventListener('click', (e) => {
    if (els.panel.hidden) return;
    if (e.target === els.scrim || !container.contains(e.target)) setOpen(false);
  });
  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape' || els.panel.hidden) return;
    /* A modal takes precedence: modalVisibility.js owns Escape while one is
       open, and consuming it here would close this panel instead of the dialog
       the user is actually looking at. */
    if (document.querySelector('.modal.show')) return;
    e.preventDefault();
    setOpen(false);
    els.trigger.focus();
  });
}

/* One function closes BOTH halves. The scrim and the panel are never toggled
   separately, which is the whole reason the scrim is not a .modal: the shared
   modal dismissal would have hidden the scrim on its own and left the panel
   sitting over unblurred content. */
function setOpen(open) {
  if (!els) return;
  els.panel.hidden = !open;
  els.scrim.hidden = !open;
  els.container.classList.toggle('is-open', open);
  els.trigger.setAttribute('aria-expanded', String(open));
  if (!open) return;
  filterQuery = '';
  els.filter.value = '';
  applyFilter();
  if (!els.filter.hidden) els.filter.focus();
  else { const first = visibleRows()[0]; if (first) first.focus(); }
  if (affordance) affordance.refresh();
}

/* ── Render ────────────────────────────────────────────────────────────── */

export function renderTabs() {
  const container = document.getElementById("tabs-container");
  if (!container) return;
  if (!els || els.container !== container) buildShell(container);

  // A deleted page must not stay selected, and an import can hand back a list
  // that no longer holds the id we were on.
  if (!activeTabs.some(t => t.id === selectedTabId)) {
    const home = activeTabs.find(t => t.type === 'search') || activeTabs[0];
    selectedTabId = home ? home.id : 'search';
  }

  els.well.innerHTML = '';
  activeTabs.forEach((tab) => {
    const row = el('button', 'page-nav-row');
    row.type = 'button';
    row.dataset.tabId = String(tab.id);
    row.dataset.name = tab.label;
    row.append(el('span', 'page-nav-check'), el('span', 'page-nav-row-name', tab.label));

    row.addEventListener('click', () => {
      selectedTabId = tab.id;
      syncSelection();
      setOpen(false);
      if (_onTabClick) _onTabClick(tab);
    });

    // R-012: right-click still opens the shared dialog over the blurred page.
    // The panel closes first, so a dialog is never layered over an open menu.
    if (tab.type !== "search") {
      row.addEventListener("contextmenu", (e) => {
        e.preventDefault();
        if (ContextMenu.disabled) return;
        setOpen(false);
        openTabDialog({
          name: tab.label,
          onRename: (newName) => {
            const t = activeTabs.find(t => t.id === tab.id);
            if (t) { t.label = newName; saveTabs(); renderTabs(); }
          },
          onDelete: () => {
            setActiveTabs(activeTabs.filter(t => t.id !== tab.id));
            if (currentBookmarkPage === tab.id) {
              if (_onNavigateToSearch) _onNavigateToSearch();
              selectSearchTab();
            }
            window.chrome.storage.sync.remove(`page${tab.id}`);
            BookmarkDB.deleteBookmarks(tab.id);
            saveTabs(); renderTabs();
          }
        });
      });
    }

    els.well.appendChild(row);
  });

  els.filter.hidden = activeTabs.length <= FILTER_THRESHOLD;
  syncSelection();
  applyFilter();
}

/** Repaint everything that names the current page: the trigger label, the
 *  position counter and the checkmark. One writer, so they cannot disagree. */
function syncSelection() {
  if (!els) return;
  els.well.querySelectorAll('.page-nav-row').forEach((row) => {
    row.classList.toggle('is-current', row.dataset.tabId === String(selectedTabId));
  });

  const index = activeTabs.findIndex(t => t.id === selectedTabId);
  const tab = index === -1 ? null : activeTabs[index];
  els.current.textContent = tab ? tab.label : 'Home';
  els.trigger.title = tab ? tab.label : 'Home';
  // One page is not a position in a list, so the counter says nothing.
  els.count.textContent = activeTabs.length > 1 ? `${index + 1}/${activeTabs.length}` : '';
}

function visibleRows() {
  return [...els.well.querySelectorAll('.page-nav-row')].filter(r => !r.hidden);
}

/* Substring match, with the matched run marked in INK only: a fill would
   collide with the hover fill. Rows are hidden rather than removed, so the
   listeners bound in renderTabs survive a filter. */
function applyFilter() {
  if (!els) return;
  const q = filterQuery.toLowerCase();
  let shown = 0;
  els.well.querySelectorAll('.page-nav-row').forEach((row) => {
    const name = row.dataset.name;
    const at = q ? name.toLowerCase().indexOf(q) : -1;
    const hit = !q || at !== -1;
    row.hidden = !hit;
    if (hit) shown++;

    const nameEl = row.querySelector('.page-nav-row-name');
    if (hit && q) {
      nameEl.textContent = '';
      nameEl.append(
        document.createTextNode(name.slice(0, at)),
        el('mark', null, name.slice(at, at + q.length)),
        document.createTextNode(name.slice(at + q.length))
      );
    } else if (nameEl.textContent !== name) {
      nameEl.textContent = name;
    }
  });
  els.empty.hidden = shown > 0;
  if (affordance) affordance.refresh();
}

/* ── Page lifecycle ────────────────────────────────────────────────────── */

/**
 * R-022: ASKS FOR A NAME FIRST.
 *
 * This used to mint "Page 3" and navigate, with no dialog anywhere, so the two
 * rows of one menu behaved completely differently: Add bookmark opened a flow and
 * Add page silently did the thing. The name step closes that gap.
 *
 * The default is a PLACEHOLDER, not a value, so pressing Enter immediately still
 * gives the old one-keystroke path while an empty field costs nothing to replace.
 * Escape creates no page, per the write-once rule from R-021.
 */
export async function addNewTab() {
  const count = activeTabs.filter(t => t.type !== 'search').length + 1;
  const { openInputPicker } = await import('../bookmarks/bookmarkDialog.js');

  openInputPicker({
    title: 'Page name',
    value: '',
    placeholder: `Page ${count}`,
    save: (raw) => {
      const label = raw.trim() || `Page ${count}`;
      createPage(label);
      return true;
    },
  });
}

/** The write half of addNewTab, separated so the dialog owns only the asking. */
function createPage(label) {
  const newId = Date.now();
  const newTab = { id: newId, label, type: 'bookmarks' };
  activeTabs.push(newTab); saveTabs();
  /* Was an alert() announcing that a page had been created. We navigate to the
     new page instead, which says the same thing by doing it; an alert is also
     the one piece of UI here that the design system cannot style. */
  selectedTabId = newId;
  renderTabs();
  if (_onTabClick) _onTabClick(newTab);
}

/* renameTab and deleteTab stood here and are DELETED. Both had zero callers
   anywhere in the codebase, and both drove the flow with prompt() and confirm(),
   the browser dialogs R-012 replaced with the picker family precisely because
   the design system cannot style them. The live path is openTabDialog, which
   offers Rename page and Delete page on the R-012 card. Removed rather than left
   as a second, uglier way to do the same two jobs. */
